def compute(vars):
    old = vars["v1"]
    new = vars["v2"]
    if old == 0:
        return None
    decrease_rate = (old - new) / old * 100
    return {
        "value": decrease_rate,
        "trace": {
            "old_development_costs": old,
            "new_development_costs": new,
            "decrease": old - new,
            "output_meta": {
                "currency": None,
                "scale": "ones",
                "unit": "percentage"
            }
        }
    }
